import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"GetBatchC","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetBatchC","slug":"getbatchc"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetBatchC.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetBatchC.md"}'),l={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetBatchC.md"};function i(r,t,p,d,o,h){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="getbatchc" tabindex="-1">GetBatchC <a class="header-anchor" href="#getbatchc" aria-label="Permalink to &quot;GetBatchC&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p><a href="./GetBatchTensorC.html">GetBatchTensorC</a>接口与该接口的功能相同，建议使用<a href="./GetBatchTensorC.html">GetBatchTensorC</a>。</p><p>调用一次GetBatchC，会获取C矩阵分片，该接口可以与<a href="./IterateNBatch.html">IterateNBatch</a>异步接口配合使用。用于在调用IterateNBatch迭代计算后，获取一片std::max(batchA, batchB) * singleCoreM * singleCoreN大小的矩阵分片。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt;</span></span>
<span class="line"><span>__aicore__ inline GlobalTensor&lt;DstT&gt; GetBatchC(uint32_t batchA, uint32_t batchB, bool enSequentialWrite = false)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void GetBatchC(const LocalTensor&lt;DstT&gt;&amp; c, uint32_t batchA, uint32_t batchB, bool enSequentialWrite = false)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sync</td><td>通过该参数设置同步或者异步模式：同步模式设置为true；异步模式设置为false，默认为同步模式。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>batchA</td><td>输入</td><td>左矩阵的batch数。</td></tr><tr><td>batchB</td><td>输入</td><td>右矩阵的batch数。</td></tr><tr><td>enSequentialWrite</td><td>输入</td><td>输出是否连续存放数据，默认false（非连续写模式）。</td></tr><tr><td>c</td><td>输入</td><td>C矩阵，用于保存矩阵分片。类型为LocalTensor。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>GlobalTensor&lt;DstT&gt;，返回计算的矩阵分片。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>当使能MixDualMaster（双主模式）场景时，即模板参数<a href="./MatmulConfig.html#p9218181073719">enableMixDualMaster</a>设置为true，不支持使用该接口。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 计算需要多Batch计算循环次数</span></span>
<span class="line"><span>int g_lay = tiling.ALayoutInfoG &gt; tiling.BLayoutInfoG ? tiling.ALayoutInfoG : tiling.BLayoutInfoG;</span></span>
<span class="line"><span>int for_exent = tiling.ALayoutInfoB * tiling.ALayoutInfoN * g_lay / tiling.BatchNum;</span></span>
<span class="line"><span>mm1.SetTensorA(gm_a[0], isTransposeAIn);</span></span>
<span class="line"><span>mm1.SetTensorB(gm_b[0], isTransposeBIn);</span></span>
<span class="line"><span>if (tiling.isBias) {</span></span>
<span class="line"><span>    mm1.SetBias(gm_bias[0]);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 多batch Matmul计算    </span></span>
<span class="line"><span>mm1.template IterateNBatch&lt;false&gt;(for_exent, batchA, batchB, false);</span></span>
<span class="line"><span>// ...other compute</span></span>
<span class="line"><span>for (int i = 0; i &lt; for_exent ; ++i) {</span></span>
<span class="line"><span>    mm1.template GetBatchC&lt;false&gt;(ubCmatrix, batchA, batchB); </span></span>
<span class="line"><span>    // ...other compute</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,20)])])}const u=a(l,[["render",i]]);export{b as __pageData,u as default};
